/* HackerRank style: grid queries and prefix tricks */
int printf(char fmt);
int scanf(char fmt, int x);

int grid_max2(int a, int b) {
    if (a > b) {
        return a;
    }
    return b;
}

int grid_min2(int a, int b) {
    if (a < b) {
        return a;
    }
    return b;
}

int grid_mix3(int a, int b, int c) {
    return a + b + c;
}

int grid_solve_0(int n, int q, int bias) {
    int arr[12];
    int pref[12]
    int i = 0;
    int j = 0;
    int ans = 0;
    int best = 0;
    int low = 0;
    int extra = 0;
    for (i = 0; i < 12; i = i + 1) {
        arr[i] = i + bias + q;
        pref[i] = 0;
    }
    best = arr[0];
    low = arr[0];
    for (i = 0; i < n; i = i + 1) {
        j = 0;
        while (j < 12) {
            pref[j] = pref[j] + arr[j];
            if (pref[j] > best) {
                best = pref[j];
            }
            if (pref[j] < low) {
                low = pref[j];
            }
            j = j + 1;
        }
        if (i < q) {
            ans = ans + arr[i];
        }
        else {
            ans = ans + pref[i % 12]
        }
        if (ans > best) {
            best = ans;
        }
        if (ans < low) {
            low = ans;
        }
        arr[i % 12] = arr[i % 12] + bias;
    }
    extra = 0;
    for (i = 0; i < q; i = i + 1) {
        extra = extra + (arr[i % 12] + pref[i % 12]);
        if (extra > best) {
            best = extra;
        }
    }
    ans = ans + grid_max2(best, low);
    ans = ans + grid_min2(best, low);
    ans = ans + grid_mix3(ans, best, extra);
    return ans;
}

int grid_solve_1(int n, int q, int bias) {
    int arr[12];
    int pref[12];
    int i = 0;
    int j = 0;
    int ans = 0;
    int best = 0;
    int low = 0;
    int extra = 0;
    for (i = 0; i < 12; i = i + 1) {
        arr[i] = i + bias + q;
        pref[i] = 0;
    }
